 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Diagonal tracks run down-right; each track encodes a phase in a cyclic
    # color sequence. Infer a compact period from the tracked diagonal offsets.
    tracks = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                d = c - r
                tracks.setdefault(d, value)
    offsets = sorted(tracks)
    if not offsets:
        return [row[:] for row in grid]
    # Find smallest period for which repeated observed offsets agree.
    period = max(1, offsets[-1] - offsets[0] + 1)
    for p in range(1, period + 1):
        vals = {}
        if all((d % p not in vals or vals[d % p] == v)
               and not vals.setdefault(d % p, v) != v
               for d, v in tracks.items()):
            period = p
            break
    # For phases not represented by a track, the cyclic order follows the
    # ordered phase/color sequence where supported by observed offsets.
    residues = {d % period: v for d, v in tracks.items()}
    known = sorted(residues)
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            phase = (c - r) % period
            if phase in residues:
                row.append(residues[phase])
            else:
                # Fill a missing phase by cycling between neighboring known phases.
                nearest = min(known, key=lambda k: ((phase-k) % period))
                row.append(residues[nearest])
        out.append(row)
    return out
